def by_length(arr):
    """
    Sorts an array of integers in descending order, filters to keep only
    integers between 1 and 9 inclusive, and converts these integers to their
    English word representations ("One" to "Nine").
    """
    def to_word(num):
        mapping = {
            1: "One", 2: "Two", 3: "Three", 4: "Four", 5: "Five",
            6: "Six", 7: "Seven", 8: "Eight", 9: "Nine"
        }
        return mapping.get(num)

    return [
        to_word(x) for x in sorted(arr, reverse=True) if 1 <= x <= 9
    ]
