def count_even_odd_digits(n):
    """Return a tuple (evens, odds) counting digits of n. Negative sign ignored."""
    n = abs(n)
    evens = 0
    odds = 0
    if n == 0:
        evens = 1
    while n:
        d = n % 10
        if d % 2 == 0:
            evens += 1
        else:
            odds += 1
        n //= 10
    return evens, odds

