def count_sevens(n: int) -> int:
    """
    Counts occurrences of digit '7' in all numbers from 0 to n-1
    that are divisible by 11 or 13.
    """
    if n <= 0:
        return 0

    def digit_count(num: int) -> int:
        """Count occurrences of digit '7' in a given number."""
        count = 0
        if num == 0:
            return 0
        while num > 0:
            if num % 10 == 7:
                count += 1
            num //= 10
        return count

    # Sum counts for numbers divisible by 11 or 13
    return sum(
        digit_count(x)
        for x in range(n)
        if x % 11 == 0 or x % 13 == 0
    )

# Example usage
if __name__ == "__main__":
    # Test with a sample value
    print(count_sevens(100))  # Output: 6
