from functools import reduce
from typing import List

def join_strings(strings: List[str], sep: str = "") -> str:
    return reduce(lambda acc, s: acc + (sep if acc and not acc.endswith(sep) else "") + s if acc else s, strings, "")

# Example
print(join_strings(["Hello", "world", "2024"], sep=" "))

