def get_larger_number(num1, num2):
    """
    Compares two numbers after converting to float (handling commas),
    returning the larger one or None if equal.

    Args:
        num1: First number (int, float, or string with optional commas)
        num2: Second number (int, float, or string with optional commas)

    Returns:
        The larger number as a float, or None if equal
    """
    def to_float(value):
        """Convert value to float, handling commas."""
        if isinstance(value, (int, float)):
            return float(value)
        # Handle string with commas
        if isinstance(value, str):
            cleaned = value.replace(',', '').strip()
            return float(cleaned)
        raise ValueError(f"Unsupported type: {type(value)}")

    try:
        float1 = to_float(num1)
        float2 = to_float(num2)

        if float1 > float2:
            return float1
        elif float2 > float1:
            return float2
        else:
            return None
    except (ValueError, TypeError) as e:
        raise ValueError(f"Invalid number format: {e}")
