def three_sum_zero(nums):
    """
    Checks if any three distinct indices in a list have values summing to zero.
    Uses functional programming style with set operations.
    """
    # Create a list of unique values with their indices to handle duplicates
    # We iterate over indices to ensure we can find distinct indices later
    n = len(nums)
    if n < 3:
        return False

    # Use a set for O(1) lookups of the complement
    # We'll check all pairs and see if the complement exists
    # Functional approach: use any() with a generator expression
    return any(
        (nums[i] + nums[j] + nums[k] == 0)
        for i in range(n)
        for j in range(i + 1, n)
        for k in range(j + 1, n)
    )

