def find_indices(matrix, x):
    """
    Return list of (row, col) indices where matrix[row][col] == x.
    Each row is scanned from right to left.
    """
    return [
        (r, c)
        for r, row in enumerate(matrix)
        for c in range(len(row) - 1, -1, -1)
        if row[c] == x
    ]
